class Solution {public:long long solve(vector<vector<int>> costs){int n=costs.size();if(n<2)return 0;int size=1<<n;long long inf=LLONG_MAX/4;vector<vector<long long>>d(size,vector<long long>(n,inf));d[1][0]=0;for(int mask=1;mask<size;mask+=2)for(int a=0;a<n;a++)if(d[mask][a]<inf)for(int b=1;b<n;b++)if(!(mask&(1<<b)))d[mask|(1<<b)][b]=min(d[mask|(1<<b)][b],d[mask][a]+costs[a][b]);long long best=inf;for(int last=1;last<n;last++)best=min(best,d[size-1][last]+costs[last][0]);return best;}};